using System;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class AssetAllocation:System.Web.UI.Page{static AssetBAL S=>new AssetBAL();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name.ToString());protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object Lookup(string type,int? parentID){return AssetBAL.Rows(S.Lookup(type,parentID));}[WebMethod]public static object List(){return AssetBAL.Rows(S.List("Allocation",null,null,"Allocated"));}[WebMethod]public static ApiResult SaveBatch(AllocationBatchInput x){try{if(x==null||x.AssetIDs==null||x.AssetIDs.Count==0)return ApiResult.Fail("Select at least one available asset.");if(x.EmployeeID<=0)return ApiResult.Fail("Employee is required.");if(x.ShiftID!=1&&x.ShiftID!=2)return ApiResult.Fail("Shift must be Day or Night.");x.ShiftName=x.ShiftID==1?"Day":"Night";return ApiResult.Ok(S.Save("usp_Assets_SaveAllocationBatch",x,U),x.AssetIDs.Count+" asset(s) allocated successfully for "+x.ShiftName+".");}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
